import React, { useEffect, useState } from 'react';
import api from '../../lib/api';

export default function AdminOrders(){
  const [orders, setOrders] = useState([]);
  const [meta, setMeta] = useState(null);
  const [loading, setLoading] = useState(false);

  async function load(page=1){
    setLoading(true);
    try{
      const r = await api.get(`/admin/orders?page=${page}`);
      const data = r.data;
      const list = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setOrders(list);
      setMeta(data?.meta || null);
    }catch(err){
      console.error('Load orders failed:', err);
      const status = err.response?.status;
      if (status === 401 || status === 403) alert('Akses admin diperlukan.');
    }finally{
      setLoading(false);
    }
  }

  useEffect(()=>{ load(); },[]);

  return (
    <div className="font-sans">
      <div className="container py-6">
        <header className="flex items-center justify-between mb-4">
          <strong className="text-lg">Admin</strong>
          <nav className="flex gap-4 text-sm">
            <a href="/admin/products" className="underline">Products</a>
            <a href="/admin/orders" className="underline">Orders</a>
            <a href="#" className="underline" onClick={(e)=>{e.preventDefault(); localStorage.removeItem('hr_token'); localStorage.removeItem('hr_user'); window.location.href='/admin/login';}}>Logout</a>
          </nav>
        </header>
        <h2 className="text-2xl font-semibold mb-4">Admin - Riwayat Pembelian</h2>
        {loading && <div>Loading...</div>}
        <div className="card p-4 overflow-x-auto">
          <table className="table min-w-full">
            <thead className="bg-gray-50">
              <tr>
                <th>ID</th>
                <th>Order</th>
                <th>Pembeli</th>
                <th>Status</th>
                <th>Total</th>
                <th>Items</th>
                <th>Waktu</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(o => (
                <tr key={o.id}>
                  <td>{o.id}</td>
                  <td><a className="text-primary underline" href={`/admin/orders/${o.id}`}>{o.order_number}</a></td>
                  <td>{o.user ? `${o.user.name} (${o.user.email})` : '-'}</td>
                  <td>
                    <span className={`badge ${o.status==='paid' || o.status==='settlement' ? 'badge-success' : (o.status==='pending' ? 'badge-warning' : 'badge-danger')}`}>{o.status}</span>
                  </td>
                  <td>Rp {o.total_amount}</td>
                  <td>{Array.isArray(o.items) ? o.items.length : (typeof o.items === 'string' ? (()=>{ try { return JSON.parse(o.items).length } catch { return '-'; } })() : '-')}</td>
                  <td>{o.created_at}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {meta && (
          <div className="mt-3 flex items-center gap-3">
            <button className="btn btn-outline" disabled={!meta?.prev_page_url} onClick={()=> load((meta.current_page||1)-1)}>Prev</button>
            <span className="text-sm">Page {meta.current_page} / {meta.last_page}</span>
            <button className="btn btn-outline" disabled={!meta?.next_page_url} onClick={()=> load((meta.current_page||1)+1)}>Next</button>
          </div>
        )}
      </div>
    </div>
  );
}
